import * as THREE from 'three';

const vintage='https://retrofret.com/products/fender-twin-reverb-ac-568-wfactory-jbls-large-combo-tube-amplifier-1968-13479';
export const twinParts=[
 {id:'speakers',label:'Speakers',title:'Where electricity becomes sound.',body:'The signal moves a coil inside a magnet. The attached paper cone pushes air, turning that movement into the sound you hear.',detail:'This study: two 12-inch Oxford-family speakers, each 8 Ω, connected in parallel for a 4 Ω load. Speaker suppliers and factory options varied; JBL D120Fs were an extra-cost option.',image:'./assets/explore/speaker-nubert.jpg',alt:'Rear of a representative loudspeaker showing its basket and magnet.',caption:'Representative loudspeaker construction. This is a Nubert driver, not a Fender, Oxford or JBL part.',credit:'Günther Nubert / Wikimedia Commons · public domain',photoSource:'https://commons.wikimedia.org/wiki/File:12zollhinten.jpg',source:'https://www.vintageguitarandbass.com/fender/catalogues/1968_32.php',sourceLabel:'1968 Fender catalog'},
 {id:'power-tubes',label:'Power tubes',title:'The muscle behind the music.',body:'Four 6L6GC power tubes work together to supply the changing electrical power that ultimately drives the speakers. The smaller tubes nearby handle earlier stages and effects.',detail:'Four large output tubes and six smaller tubes are shown. Their envelopes and positions are a teaching approximation, not a socket-by-socket service diagram.',image:'./assets/explore/6l6gc-joe-haupt.jpg',alt:'Vintage RCA 6L6GC glass power tubes photographed on a light background.',caption:'Representative vintage RCA 6L6GC tubes made for McIntosh. Not the tubes from this Fender specimen.',credit:'Joe Haupt · CC BY-SA 2.0 · unmodified photograph',photoSource:'https://commons.wikimedia.org/wiki/File:Vintage_RCA_Blackplate_6L6GC_Vacuum_Tubes_Made_For_McIntosh,_Made_In_USA_(15643635699).jpg',license:'https://creativecommons.org/licenses/by-sa/2.0/',source:'https://support.fender.com/hc/en-us/articles/42507659450779-What-tubes-are-in-my-amp',sourceLabel:'Fender tube reference'},
 {id:'output-transformer',label:'Output transformer',title:'Connecting tubes to speakers.',body:'The output transformer couples the power tubes to the speakers, matching their very different electrical needs. Its coils and iron core transfer the changing audio signal.',detail:'The dark laminated block is an approximate construction marker. Exact 1968 mounting position, dimensions and winding details still need to be established. It is distinct from the mains power transformer.',source:vintage,sourceLabel:'See the vintage Twin photo gallery',empty:'Vintage chassis photographs are available in the linked gallery. An approved close-up is not yet embedded.'}
];

// DOM buttons project from actual part groups, so labels follow orbit and resize.
export function createExploration({host,stage,camera,stopMotion}){
 const layer=document.createElement('div');layer.className='part-hotspots';layer.hidden=true;host.append(layer);
 const panel=document.createElement('section');panel.className='part-card';panel.hidden=true;panel.setAttribute('aria-label','Selected amplifier part');stage.append(panel);
 const hint=document.createElement('p');hint.className='inside-hint';hint.textContent='Explore the construction · select a part';hint.hidden=true;stage.append(hint);
 const nav=document.createElement('div');nav.className='part-nav';nav.hidden=true;nav.setAttribute('role','group');nav.setAttribute('aria-label','Explore internal components');stage.append(nav);
 let model=null,enabled=false,selected=null,anchors=[],lastButton=null;const v=new THREE.Vector3();const bounds=new THREE.Box3();
 const buttons=twinParts.map(part=>{const b=document.createElement('button');b.className='part-hotspot';b.textContent=part.label;b.setAttribute('aria-label',`Learn about ${part.label.toLowerCase()}`);b.setAttribute('aria-expanded','false');b.setAttribute('aria-controls',`part-info`);b.onclick=()=>select(part.id,b);layer.append(b);const n=document.createElement('button');n.textContent=part.label;n.onclick=()=>select(part.id,n);n.setAttribute('aria-expanded','false');nav.append(n);return {part,b,n};});
 panel.id='part-info';
 function clear(focus=false){panel.hidden=true;selected=null;stage.classList.remove('part-selected');buttons.forEach(({b,n})=>{b.setAttribute('aria-expanded','false');n.setAttribute('aria-expanded','false')});if(focus)lastButton?.focus();}
 function select(id,button){stopMotion();lastButton=button;selected=id;const p=twinParts.find(p=>p.id===id);stage.classList.add('part-selected');panel.hidden=false;panel.innerHTML=`<button class="part-close" aria-label="Close part information">×</button><span class="eyebrow">INSIDE THE TWIN / ${p.label.toUpperCase()}</span><h2>${p.title}</h2><p>${p.body}</p>${p.image?`<figure><img src="${p.image}" alt="${p.alt}"><figcaption>${p.caption}</figcaption></figure><p class="photo-credit"><a href="${p.photoSource}" target="_blank" rel="noopener noreferrer">${p.credit}</a>${p.license?` · <a href="${p.license}" target="_blank" rel="noopener noreferrer">License</a>`:''}</p>`:`<p class="photo-pending">${p.empty}</p>`}<p class="part-detail">${p.detail}</p><a class="part-source" href="${p.source}" target="_blank" rel="noopener noreferrer">${p.sourceLabel}</a>`;panel.querySelector('button').onclick=()=>clear(true);buttons.forEach(({part,b,n})=>{b.setAttribute('aria-expanded',String(part.id===id));n.setAttribute('aria-expanded',String(part.id===id))});panel.querySelector('button').focus({preventScroll:true});}
 panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();clear(true)}});
 return {
  attach(next){clear();model=next;anchors=[];model?.traverse(o=>{if(o.userData.explorePart)anchors.push(o)});stage.classList.toggle('construction-demo',!!model?.userData.exploration);this.setInside(false);},
  setInside(on){enabled=!!model?.userData.exploration&&on;layer.hidden=!enabled;nav.hidden=!enabled;hint.hidden=!enabled;stage.classList.toggle('inside-demo',enabled);model?.traverse(o=>{if(o.userData.insideRemovable)o.visible=!enabled});if(!enabled)clear();},
  update(){if(!enabled)return;model.updateWorldMatrix(true,true);buttons.forEach(({part,b})=>{const o=anchors.find(o=>o.userData.explorePart===part.id);if(!o){b.hidden=true;return;}bounds.setFromObject(o);bounds.getCenter(v);v.project(camera);const x=(v.x*.5+.5)*host.clientWidth,y=(-v.y*.5+.5)*host.clientHeight;const off=v.z< -1||v.z>1||x<10||x>host.clientWidth-10||y<10||y>host.clientHeight-10;b.hidden=off;b.style.left=`${x}px`;b.style.top=`${y}px`;b.classList.toggle('selected',selected===part.id);});}
 };
}
